-- Seeds three rooms: a welcome hall, an events plaza and a garden lounge.
-- Run it in Adminer against the hotel database. It is safe to run again.
-- Rooms are owned by the oldest account (see @owner). Room images load from @site.
SET @owner = (SELECT MIN(id) FROM users);
SET @site = 'https://retro.steamvaluechecker.com';

DELETE i FROM items i JOIN rooms r ON r.id = i.room_id WHERE r.owner = @owner AND r.model_name IN ('lucado_welcome','lucado_plaza','lucado_garden','lucado_lobby');
DELETE FROM rooms WHERE owner = @owner AND model_name IN ('lucado_welcome','lucado_plaza','lucado_garden','lucado_lobby');
DELETE FROM room_models WHERE id IN ('lucado_welcome','lucado_plaza','lucado_garden','lucado_lobby');

-- Welcome to Lucado Hotel
SET @room = LAST_INSERT_ID();

-- Lucado Plaza
SET @room = LAST_INSERT_ID();

-- The Garden Lounge
SET @room = LAST_INSERT_ID();
